/** Actual Payroll controllers run with synthetic fetch responses only; no network or financial writes. */
const {test}=require('node:test');
const assert=require('node:assert/strict');
const {fixtures:f,harness,ok,fail,settle,modelFile,nodes,text,expand}=require('./payroll-test-helper.cjs');
function check(name,fn,target,file){test('Payroll behavior: '+name,async()=>{const h=harness(target,file);try{await fn(h);}finally{h.cleanup();}});}
const routes={register:'',run:'/runs/syn-run',entry:'/runs/syn-run/entries/syn-entry',entry_edit:'/runs/syn-run/entries/syn-entry/edit',profile:'/profiles/syn-profile',profile_edit:'/profiles/syn-profile/edit',profile_new:'/profiles/new',period_new:'/periods/new',run_new:'/runs/new',withholding_new:'/withholdings/new',policy_new:'/policy/new',approve:'/runs/syn-run/approve',pay:'/runs/syn-run/pay'};
async function ready(h,mode='register',overrides={}){h.pathname('/dashboard/payroll'+routes[mode]);if(Object.keys(overrides).length)h.response((url,options)=>{if(!options?.method){for(const [key,value]of Object.entries(overrides)){if((key==='run'&&url.startsWith('/api/payroll/runs/'))||(key==='policy'&&url.startsWith('/api/payroll/policy'))||(key==='profiles'&&url==='/api/payroll/salary-profiles')||(key==='meta'&&url==='/api/payroll/meta')||(key==='periods'&&url==='/api/payroll/periods'))return ok(value);}}return h.defaultResponse(url,options);});await h.mount();await h.flush();let vm=h.render();await h.flush();vm=h.render();return vm;}
function change(h,values){const vm=h.render();for(const [key,value]of Object.entries(values))vm.change(key,value);return h.render();}
async function fields(h,mode,overrides={}){await ready(h,mode,overrides);const v={profile_new:{employee_id:f.profile.employee_id,currency:'USD',base_salary:'9007199254740993.01',effective_from:'2026-11-01'},profile_edit:{base_salary:'1300.13'},period_new:{name:'Synthetic November',period_start:'2026-11-01',period_end:'2026-11-30',pay_date:'2026-12-01'},run_new:{period_id:f.period.id,currency:'USD'},entry_edit:{tax_amount:'11.05',adjustment_reason:'Reviewed synthetic adjustment'},withholding_new:{account_id:'syn-account',amount:'20.10'},policy_new:{mode:'calendar_day',effective_from:'2026-11-01',activation_reason:'Reviewed synthetic future policy'},pay:{account_id:'syn-account'},approve:{}}[mode];change(h,v);await h.flush();h.render();if(mode==='run_new'){await h.render().requestPreview();h.render();}return h.render();}
const writes=h=>h.requests.filter(r=>r.options?.method&& !r.url.endsWith('/preview'));
const bodies=h=>writes(h).map(r=>r.options.body===undefined?undefined:JSON.parse(r.options.body));
check('browse only reads run list and policy, never first-run detail or any write',async h=>{const vm=await ready(h);assert.equal(vm.ready,true);assert.deepEqual(h.requests.map(r=>r.url),['/api/payroll/runs','/api/payroll/policy']);assert.equal(vm.run,undefined);assert.equal(writes(h).length,0);});
for(const perms of [[],['payroll.view']])check(`editor access ${perms.join(',')||'none'} does not load or mutate without both read/manage`,async h=>{h.permissions(perms);const vm=await fields(h,'period_new');await vm.save();assert.equal(writes(h).length,0);});
check('viewer can read saved document but cannot submit or fetch editable setup',async h=>{h.permissions(['payroll.view']);const vm=await ready(h,'run');assert.equal(vm.run.id,f.run.id);assert.equal(vm.canManage,false);await vm.save();assert.equal(writes(h).length,0);});
check('wildcard manager retains authorized read and write capability',async h=>{h.permissions(['*']);const vm=await fields(h,'period_new');assert.equal(vm.canSubmit,true);await vm.save();assert.equal(writes(h).length,1);});
check('independent failed policy read does not erase successfully verified list',async h=>{h.response((url,options)=>url.endsWith('/policy')?fail(503):h.defaultResponse(url,options));const vm=await ready(h);assert.equal(vm.data.runs.length,1);assert.match(vm.errors.policy,/Synthetic/);assert.equal(vm.ready,false);});
check('malformed 200 money row fails closed rather than rendering invented zero',async h=>{h.response((url,options)=>url==='/api/payroll/runs'?ok([{...f.run,net_total:1202.34}]):h.defaultResponse(url,options));const vm=await ready(h);assert.equal(vm.data.runs,undefined);assert.match(vm.errors.runs,/could not be verified/);});
for(const status of [401,403])check(`current read ${status} is authoritative without leaked data`,async h=>{h.response(()=>fail(status));const vm=await ready(h,'run');assert.equal(vm.run,undefined);assert.equal(vm.ready,false);assert.equal(h.navigation.some(n=>n[1]==='/login'),status===401);});
check('late unmounted read401 neither redirects nor fills a stale document',async h=>{h.pathname('/dashboard/payroll/runs/syn-run');let resolve;h.response(()=>new Promise(r=>resolve=r));h.render();await h.flush();h.unmount();resolve(fail(401));await settle();const vm=h.render();assert.equal(vm.run,undefined);assert.equal(h.navigation.length,0);});
check('old route read cannot replace newer run or redirect its session',async h=>{h.pathname('/dashboard/payroll/runs/old');let resolve;h.response(url=>url.endsWith('/old')?new Promise(r=>resolve=r):ok({...f.run,id:'new-run'}));h.render();await h.flush();h.pathname('/dashboard/payroll/runs/new-run');h.render();await h.flush();h.render();resolve(fail(401));await settle();assert.equal(h.render().run.id,'new-run');assert.equal(h.navigation.length,0);});
check('URL tab change immediately hides resources from prior route specification',async h=>{await ready(h);h.query('tab=profiles');const vm=h.render();assert.equal(vm.data.runs,undefined);assert.equal(vm.data.profiles,undefined);assert.equal(vm.anyLoading,true);await h.flush();assert.equal(h.render().data.profiles[0].id,f.profile.id);});
for(const mode of ['profile_edit','entry_edit'])check(`${mode} initializes authoritative fields once, refresh preserves unsaved edits`,async h=>{await ready(h,mode);let vm=h.render();assert.equal(vm.dirty,false);vm.change('notes','Retained edit');h.render();h.response((url,options)=>url.includes('salary-profiles')?ok([{...f.profile,notes:'New server value'}]):url.startsWith('/api/payroll/runs/')?ok({...f.run,entries:[{...f.entry,notes:'New server value'}]}):h.defaultResponse(url,options));await h.render().load();h.render();await h.flush();vm=h.render();assert.equal(vm.values.notes,'Retained edit');assert.equal(vm.dirty,true);});
check('profile immutable keys ignore programmatic change, not just disabled controls',async h=>{await ready(h,'profile_edit');const before={...h.render().values};change(h,{employee_id:'evil',currency:'EUR',pay_frequency:'weekly',effective_from:'1990-01-01'});for(const key of ['employee_id','currency','pay_frequency','effective_from'])assert.equal(h.render().values[key],before[key]);});
check('legacy saved entry ignores base override despite current active v1 company policy',async h=>{await ready(h,'entry_edit');h.render().change('base_salary','99.99');assert.equal(h.render().values.base_salary,'1200.00');});
for(const status of ['approved','paid','reversed'])check(`${status} finalized entry cannot be edited or submitted`,async h=>{const vm=await fields(h,'entry_edit',{run:{...f.run,status,policy_version_id:'syn-policy'}});assert.equal(vm.unlocked,false);assert.equal(vm.canSubmit,false);await vm.save();assert.equal(writes(h).length,0);});
for(const mode of ['profile_new','profile_edit','period_new','entry_edit','withholding_new','policy_new','approve','pay','run_new'])check(`${mode} exact write route/method and known commit latch`,async h=>{const overrides=mode==='pay'?{run:{...f.run,status:'approved'}}:mode==='entry_edit'?{run:{...f.run,policy_version_id:'syn-policy'}}:{};const vm=await fields(h,mode,overrides);assert.equal(vm.canSubmit,true,JSON.stringify({mode,errors:vm.errors,values:vm.values,ready:vm.ready}));const count=h.requests.length;await vm.save();const row=writes(h)[0];const expected={profile_new:'salary-profiles',profile_edit:'salary-profiles/syn-profile',period_new:'periods',entry_edit:'runs/syn-run/entries/syn-entry',withholding_new:'withholdings/payments',policy_new:'policy-versions',approve:'runs/syn-run/approve',pay:'runs/syn-run/pay',run_new:'runs'}[mode];assert.equal(row.url,'/api/payroll/'+expected);assert.equal(row.options.method,['profile_edit','entry_edit'].includes(mode)?'PATCH':'POST');assert.equal(row.options.headers['Content-Type'],'application/json');assert.equal(h.requests.length,count+1,'no hidden read-after-write failure coupling');assert.equal(h.render().committed,true);await h.render().save();await vm.save();assert.equal(writes(h).length,1);});
check('actual profile write preserves >2^53 decimal cents and excludes immutable PATCH keys',async h=>{const vm=await fields(h,'profile_new');await vm.save();assert.equal(bodies(h)[0].base_salary,'9007199254740993.01');assert.equal(typeof bodies(h)[0].base_salary,'string');});
for(const version of [0,1])check(`actual v${version} creation uses reviewed server payload without browser totals`,async h=>{await fields(h,'run_new');if(!version){h.response((url,options)=>url.endsWith('/preview')?ok({...f.preview,mode:'manual',policy_version:0,calculation:{...f.preview.calculation,mode:'manual',policy_version:0,policy_id:null}}):h.defaultResponse(url,options));await h.render().requestPreview();h.render();}await h.render().save();assert.deepEqual(bodies(h)[0],{period_id:f.period.id,currency:'USD',...(version?{expected_calculation_hash:f.hash}:{})});});
check('same-render old save cannot submit draft modified synchronously before rerender',async h=>{const old=await fields(h,'period_new');old.change('name','New name before render');await old.save();assert.equal(writes(h).length,0);await h.render().save();assert.equal(bodies(h)[0].name,'New name before render');});
check('synchronous double-click produces one mutation before a state render',async h=>{const vm=await fields(h,'period_new');let resolve;h.response(()=>new Promise(r=>resolve=r));const first=vm.save();const second=vm.save();assert.equal(writes(h).length,1);assert.equal(h.render().saving,true);resolve(ok({id:'saved-period'}));await Promise.all([first,second]);assert.equal(h.render().committed,true);});
check('pending mutation blocks field change, reload, save and guarded Back',async h=>{const vm=await fields(h,'period_new');let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=vm.save();const busy=h.render(),before={...busy.values};busy.change('name','must not change');await busy.load();busy.back();await busy.save();assert.deepEqual(h.render().values,before);assert.equal(h.requests.length,1);assert.equal(h.navigation.length,0);const guard=h.guardCalls.filter(c=>c.kind==='state').at(-1);assert.equal(guard.options.documentLabel,'payroll');assert.equal(guard.options.isBusy,true);resolve(fail(422));await pending;});
for(const mode of ['approve','pay','withholding_new','policy_new','run_new'])check(`${mode} explicit confirmation cancellation causes zero mutation and preserves input`,async h=>{const vm=await fields(h,mode,mode==='pay'?{run:{...f.run,status:'approved'}}:{}),before={...vm.values};h.confirm(false);await vm.save();assert.equal(writes(h).length,0);assert.deepEqual(h.render().values,before);assert.equal(h.render().committed,false);assert.equal(h.prompts.length,1);});
check('approve confirmation states accrual lock not payment and uses exact server net',async h=>{const vm=await fields(h,'approve',{run:{...f.run,net_total:'9007199254740993.01'}});h.confirm(false);await vm.save();assert.match(h.prompts[0],/USD 9,007,199,254,740,993.01/);assert.match(h.prompts[0],/accrual.*locks/);assert.match(h.prompts[0],/does not pay/);});
check('pay confirmation identifies currency, net and account before posting cash settlement',async h=>{const vm=await fields(h,'pay',{run:{...f.run,status:'approved'}});h.confirm(false);await vm.save();assert.match(h.prompts[0],/USD 1,202.34/);assert.match(h.prompts[0],/Synthetic USD account/);assert.match(h.prompts[0],/cash payment.*settles payroll payable/);});
for(const account of ['syn-eur-account','syn-disabled','missing'])check(`pay rejects inappropriate account ${account}`,async h=>{await fields(h,'pay',{run:{...f.run,status:'approved'}});const vm=change(h,{account_id:account});assert.equal(vm.canSubmit,false);await vm.save();assert.equal(writes(h).length,0);});
for(const status of [400,409,422])check(`rejected ${status} save retains all inputs/dirty and does not claim committed`,async h=>{const vm=await fields(h,'period_new'),before={...vm.values};h.response(()=>fail(status,'Synthetic definite rejection'));await vm.save();const now=h.render();assert.deepEqual(now.values,before);assert.equal(now.dirty,true);assert.equal(now.committed,false);assert.equal(now.uncertain,false);assert.match(now.error,/definite rejection/);});
for(const response of [null,{id:'syn-created'}])check(`known success ${response===null?'null':'identified'} has receipt without reload or duplicate submit`,async h=>{const vm=await fields(h,'period_new');h.response(()=>ok(response));await vm.save();const now=h.render();assert.equal(now.committed,true);assert.equal(now.dirty,false);assert.equal(now.canSubmit,false);assert.equal(h.requests.length,1);now.openSaved();assert.equal(h.navigation[0][0],'navigate');assert.deepEqual(h.navigation[0][2],{replace:true,discard:true});});
check('2xx malformed JSON is known commit, not retriable write failure',async h=>{const vm=await fields(h,'period_new');h.response(()=>({...ok(null),json:async()=>{throw Error('Synthetic unreadable response');}}));await vm.save();assert.equal(h.render().committed,true);assert.equal(h.render().error,null);assert.equal(writes(h).length,1);});
check('post-commit navigation refusal leaves immutable recovery receipt without another POST',async h=>{const vm=await fields(h,'period_new');await vm.save();h.navFail(true);h.render().openSaved();await h.render().save();assert.equal(h.render().committed,true);assert.equal(writes(h).length,1);assert.equal(h.navigation.length,0);});
for(const kind of ['network','server'])check(`${kind} uncertainty retains fields and blocks blind financial retry`,async h=>{const vm=await fields(h,'withholding_new'),before={...vm.values};h.response(()=>kind==='network'?Promise.reject(new Error('Synthetic lost response')):fail(503));await vm.save();const now=h.render();assert.equal(now.uncertain,true);assert.deepEqual(now.values,before);assert.equal(now.committed,false);assert.equal(now.canSubmit,false);await now.save();assert.equal(writes(h).length,1);});
check('late unmounted write401 cannot redirect new identity',async h=>{const vm=await fields(h,'period_new');let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=vm.save();h.unmount();resolve(fail(401));await pending;assert.equal(h.navigation.length,0);assert.equal(h.render().error,null);});
check('current write401 remains authoritative with retained inputs',async h=>{const vm=await fields(h,'period_new'),before={...vm.values};h.response(()=>fail(401));await vm.save();assert.deepEqual(h.render().values,before);assert.ok(h.navigation.some(n=>n[1]==='/login'));});
for(const field of ['period_id','currency'])check(`${field} change immediately invalidates hash and stale save handler`,async h=>{const old=await fields(h,'run_new');assert.equal(old.preview.calculation_hash,f.hash);old.change(field,field==='currency'?'EUR':'other-period');await old.save();const now=h.render();assert.equal(now.preview,null);assert.equal(now.canSubmit,false);assert.equal(writes(h).length,0);});
check('late old preview cannot repopulate changed currency',async h=>{await fields(h,'run_new');let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=h.render().requestPreview();h.render().change('currency','EUR');h.render();resolve(ok(f.preview));await pending;assert.equal(h.render().preview,null);assert.equal(h.render().canSubmit,false);});
check('newer preview wins over older response and older401 does not redirect',async h=>{await fields(h,'run_new');const delayed=[];h.response(()=>new Promise(r=>delayed.push(r)));const first=h.render().requestPreview(),second=h.render().requestPreview();delayed[1](ok({...f.preview,calculation_hash:'b'.repeat(64),calculation:{...f.preview.calculation,calculation_hash:'b'.repeat(64)}}));await second;delayed[0](fail(401));await first;assert.equal(h.render().preview.calculation_hash,'b'.repeat(64));assert.equal(h.navigation.length,0);});
for(const patch of [{calculation_hash:'bad'},{calculation:{...f.preview.calculation,currency:'EUR'}}])check('invalid or mismatched-currency preview cannot authorize create',async h=>{await fields(h,'run_new');h.response(()=>ok({...f.preview,...patch}));await h.render().requestPreview();const now=h.render();assert.equal(now.preview,null);assert.match(now.previewError,/could not be verified/);assert.equal(now.canSubmit,false);});
for(const code of ['PAYROLL_PREVIEW_STALE','PAYROLL_PREVIEW_REQUIRED','PAYROLL_SETUP_REQUIRED'])check(`${code}409 retains input, removes reviewed hash, never auto retries`,async h=>{const vm=await fields(h,'run_new'),before={...vm.values};h.response(()=>fail(409,{code,issues:[{code:'PROFILE_GAP',message:'Synthetic gap',employee_id:f.profile.employee_id,profile_ids:[]}]}));await vm.save();const now=h.render();assert.deepEqual(now.values,before);assert.equal(now.preview,null);assert.equal(now.canSubmit,false);assert.equal(now.issues[0].code,'PROFILE_GAP');assert.equal(writes(h).length,1);assert.doesNotMatch(now.error,/\[object Object\]/);await now.save();assert.equal(writes(h).length,1);});
check('changed authoritative policy invalidates an already-reviewed preview',async h=>{await fields(h,'run_new');h.response((url,options)=>url.startsWith('/api/payroll/policy')?ok({...f.policy,latest_version:2,effective_policy:{...f.policyVersion,version:2,id:'syn-policy-2'}}):h.defaultResponse(url,options));await h.render().load();h.render();await h.flush();const now=h.render();assert.equal(now.preview,null);assert.equal(now.canSubmit,false);});
check('setup-only preview exposes named issues and never permits partial draft',async h=>{await fields(h,'run_new');const blocked={ready:false,policy_version:1,mode:'calendar_day',calculation_hash:null,calculation:null,setup_issues:[{code:'PROFILE_GAP',message:'Synthetic gap',employee_id:f.profile.employee_id,profile_ids:[]}]};h.response(()=>ok(blocked));await h.render().requestPreview();const now=h.render();assert.deepEqual(now.preview,blocked);assert.equal(now.canSubmit,false);await now.save();assert.equal(writes(h).length,0);});
check('policy configuration requires explicit weekdays and holiday rule in working mode',async h=>{await fields(h,'policy_new');let vm=change(h,{mode:'working_day'});assert.equal(vm.canSubmit,false);vm=change(h,{weekdays:[0,1,2,3,4]});assert.equal(vm.canSubmit,false);vm=change(h,{holiday_treatment:'exclude'});assert.equal(vm.canSubmit,true);vm=change(h,{weekdays:[0,0]});assert.equal(vm.canSubmit,false);});
for(const v1 of [false,true])check(`UI reason is required for ${v1?'v1':'legacy'} adjustment with additive audited reason and legacy base immutability`,async h=>{await fields(h,'entry_edit',{run:{...f.run,policy_version_id:v1?'syn-policy':null}});let vm=change(h,{adjustment_reason:''});assert.equal(vm.canSubmit,false);vm=change(h,{adjustment_reason:'Reviewed change'});assert.equal(vm.canSubmit,true);await vm.save();assert.equal(bodies(h)[0].adjustment_reason,'Reviewed change');assert.equal('base_salary' in bodies(h)[0],v1);});
check('Cancel/back uses dirty guard and no cancellation mutation',async h=>{const vm=await fields(h,'period_new'),before={...vm.values};h.confirm(false);vm.back();assert.equal(h.navigation.length,0);assert.equal(writes(h).length,0);assert.deepEqual(h.render().values,before);h.confirm(true);h.render().back();assert.equal(h.navigation[0][0],'navigate');});
check('source model retains full decimal amount through current handler',async h=>{assert.equal(h.load(modelFile).payrollMoney('9999999999999999.99','USD'),'USD 9,999,999,999,999,999.99');});
check('same-event Back is blocked by synchronous pendingRef before React rerenders',async h=>{const vm=await fields(h,'period_new');let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=vm.save();vm.back();assert.equal(h.navigation.length,0);resolve(fail(422));await pending;});
check('unmounted preview cannot redirect or repopulate tenant-bound result',async h=>{await fields(h,'run_new');let resolve;h.response(()=>new Promise(r=>resolve=r));const pending=h.render().requestPreview();h.unmount();resolve(fail(401));await pending;assert.equal(h.navigation.length,0);assert.equal(h.render().preview,null);});
check('changing input before calling old preview callback cannot send mismatched query',async h=>{const old=await fields(h,'run_new'),count=h.requests.length;old.change('currency','EUR');await old.requestPreview();assert.equal(h.requests.length,count);});
check('structured setup error retains valid issue rows only, without object stringification',async h=>{h.response(()=>fail(409,{code:'PAYROLL_SETUP_REQUIRED',issues:[{code:'PROFILE_GAP',message:'Synthetic gap',employee_id:null,profile_ids:[]},{code:1,message:'Bad shape'}]}));const api=h.load('src/components/payroll/payroll-api.ts');await assert.rejects(api.payrollRequest('/api/payroll/runs'),err=>err.status===409&&err.code==='PAYROLL_SETUP_REQUIRED'&&err.issues.length===1&&!err.message.includes('[object Object]'));});
check('Pydantic field errors remain legible and HTTP status retained',async h=>{h.response(()=>fail(422,[{loc:['body','base_salary'],msg:'Synthetic required amount'}]));await assert.rejects(h.load('src/components/payroll/payroll-api.ts').payrollRequest('/api/payroll/salary-profiles'),err=>err.status===422&&/base_salary.*Synthetic required amount/.test(err.message));});
check('v1 actual adjustment sends decimal strings, exact fields and required reason only',async h=>{await fields(h,'entry_edit',{run:{...f.run,policy_version_id:'syn-policy'}});const vm=change(h,{base_salary:'0.13',tax_amount:'0.01',notes:'',allowances:[{name:' Bonus ',amount:'0.05',source_profile_id:'not-outbound'}],deductions:[],adjustment_reason:' Reviewed exact cents '});await vm.save();assert.deepEqual(bodies(h)[0],{base_salary:'0.13',adjustment_reason:'Reviewed exact cents',allowances:[{name:'Bonus',amount:'0.05'}],deductions:[],tax_amount:'0.01',notes:''});});
check('profile actual PATCH retains only mutable fields and exact nullable end',async h=>{await fields(h,'profile_edit');const vm=change(h,{base_salary:'1300.13',effective_to:'',is_active:false,notes:''});await vm.save();assert.deepEqual(bodies(h)[0],{base_salary:'1300.13',default_allowances:[f.component],default_deductions:[],effective_to:null,is_active:false,notes:null});});
check('blank/invalid working calendar or reason never activates a policy silently',async h=>{await fields(h,'policy_new');for(const patch of [{mode:''},{mode:'working_day',weekdays:[],holiday_treatment:'exclude'},{mode:'working_day',weekdays:[7],holiday_treatment:'exclude'},{mode:'working_day',weekdays:[0],holiday_treatment:''},{mode:'calendar_day',activation_reason:' '}]){const vm=change(h,patch);assert.equal(vm.canSubmit,false);await vm.save();}assert.equal(writes(h).length,0);});
check('credit-card account cannot pay payroll even if active and matching currency',async h=>{const vm=await fields(h,'pay',{run:{...f.run,status:'approved'},meta:{...f.meta,accounts:[{...f.meta.accounts[0],account_type:'credit_card'}]}});assert.equal(vm.canSubmit,false);await vm.save();assert.equal(writes(h).length,0);});
const uiFile='src/components/payroll/payroll-ui.tsx',breakdownFile='src/components/payroll/payroll-breakdown.tsx';
check('money input retains decimal text and does not use native Number coercion',h=>{const changes=[],tree=h.component(uiFile,'PayrollMoneyInput',{value:'9007199254740993.01',onChange:v=>changes.push(v),required:true,label:'Base salary'});assert.equal(tree.type,'input');assert.equal(tree.props.type,'text');assert.equal(tree.props.inputMode,'decimal');assert.equal(tree.props.required,true);assert.equal(tree.props['aria-label'],'Base salary');tree.props.onChange({target:{value:'9999999999999999.99'}});assert.deepEqual(changes,['9999999999999999.99']);});
check('component editor preserves duplicate named rows and exact change/add/remove callbacks',h=>{const changes=[],items=[{name:'Bonus',amount:'0.01'},{name:'Bonus',amount:'0.02'}];let tree=expand(h.component(uiFile,'PayrollComponentsEditor',{title:'Allowances',items,onChange:v=>changes.push(v)}));const inputs=nodes(tree,'input');assert.equal(inputs.length,4);inputs[3].props.onChange({target:{value:'9007199254740993.01'}});assert.deepEqual(changes[0],[items[0],{name:'Bonus',amount:'9007199254740993.01'}]);nodes(tree,'button').find(n=>n.props['aria-label']==='Remove allowances row 1').props.onClick();assert.deepEqual(changes[1],[items[1]]);nodes(tree,'button').find(n=>text(n)==='Add').props.onClick();assert.deepEqual(changes[2],[...items,{name:'',amount:'0'}]);});
check('read components display both same-name rows rather than deduping financial data',h=>{const tree=h.component(uiFile,'PayrollComponents',{title:'Allowances',items:[{name:'Bonus',amount:'0.01'},{name:'Bonus',amount:'0.02'}],currency:'USD'});assert.equal(nodes(tree,'dt').length,2);assert.match(text(tree),/USD 0.01/);assert.match(text(tree),/USD 0.02/);});
check('totals are exactly server values and one native currency, not client recomputation',h=>{const tree=h.component(uiFile,'PayrollTotals',{record:{...f.run,net_total:'9007199254740993.01',gross_total:'0.01'}});assert.match(text(tree),/USD 9,007,199,254,740,993.01/);assert.match(text(tree),/Gross payUSD 0.01/);assert.match(text(tree),/Server-calculated/);});
check('legacy missing snapshot is labeled without reconstructing a day calculation',h=>{const tree=h.component(breakdownFile,'PayrollBreakdown',{snapshot:null,currency:'USD'});assert.match(text(tree),/Legacy calculation/);assert.match(text(tree),/not reconstructed/);assert.equal(nodes(tree,'details').length,0);});
check('snapshot disclosure retains exact huge fractions and labels recurring display approximate',h=>{const snapshot={method:'working_day',policy:{version:1,config:{allowance_treatment:'fixed_latest',deduction_treatment:'fixed_latest'}},timezone:'Asia/Dhaka',holiday_dates:['2026-11-01'],slices:[{profile_id:'syn-profile',eligible_start:'2026-11-01',eligible_end:'2026-11-01',cycle_start:'2026-11-01',cycle_end:'2026-11-30',numerator:1,denominator:26,cycle_base_salary:'0.13',unrounded_base:'0.005',unrounded_base_fraction:{numerator:'90071992547409931234567',denominator:'260000000000000000000000'},unrounded_base_is_approximation:true}]};let tree=h.component(breakdownFile,'PayrollBreakdown',{snapshot,currency:'USD'});assert.doesNotMatch(text(tree),/90071992547409931234567/);tree.props.onToggle({currentTarget:{open:true}});tree=expand(h.component(breakdownFile,'PayrollBreakdown',{snapshot,currency:'USD'}));assert.match(text(tree),/90071992547409931234567 \/ 260000000000000000000000/);assert.match(text(tree),/Approximate decimal; exact fraction retained/);assert.match(text(tree),/1 \/ 26/);assert.match(text(tree),/not a browser recalculation/);});
check('large snapshot display pages slices without changing server financial result',h=>{const snapshot={method:'calendar_day',slices:Array.from({length:27},(_,i)=>({profile_id:'profile-'+i}))};let tree=h.component(breakdownFile,'PayrollBreakdown',{snapshot,currency:'USD'});tree.props.onToggle({currentTarget:{open:true}});tree=expand(h.component(breakdownFile,'PayrollBreakdown',{snapshot,currency:'USD'}));assert.equal(nodes(tree,'article').length,25);assert.match(text(tree),/Showing 25 of 27/);nodes(tree,'button')[0].props.onClick();tree=expand(h.component(breakdownFile,'PayrollBreakdown',{snapshot,currency:'USD'}));assert.equal(nodes(tree,'article').length,27);assert.equal(nodes(tree,'button').length,0);});
check('manual snapshot explicitly denies automatic proration',h=>{const props={snapshot:{method:'manual_latest_overlapping_profile',automatic_proration:false},currency:'USD'};h.component(breakdownFile,'PayrollBreakdown',props).props.onToggle({currentTarget:{open:true}});assert.match(text(expand(h.component(breakdownFile,'PayrollBreakdown',props))),/No automatic day proration was applied/);});
check('adjustment history keeps immutable initial record distinct from before/after current changes',h=>{const before={base_salary:'100.00',allowance_total:'0.00',deduction_total:'0.00',tax_amount:'0.00',gross_pay:'100.00',net_pay:'100.00'},after={...before,base_salary:'9007199254740993.01'},tree=expand(h.component(breakdownFile,'PayrollAdjustmentHistory',{adjustments:[{id:'syn-adjustment',reason:'Reviewed synthetic correction',created_at:'2026-10-26T00:00:00Z',before,after}],currency:'USD'}));assert.match(text(tree),/Reviewed synthetic correction/);assert.match(text(tree),/Before/);assert.match(text(tree),/After/);assert.match(text(tree),/USD 9,007,199,254,740,993.01/);});

