check('known commit renders receipt only, no repeated submission or coupled reload',async h=>{await fields(h,'period_new');await h.render().save();const tree=expand(h.component(workspaceFile,'PayrollContent'));assert.match(text(tree),/Payroll action recorded/);assert.match(text(tree),/Do not submit it again/);assert.equal(nodes(tree,'form').length,0);assert.equal(h.requests.length,1);nodes(tree,'button').find(n=>text(n)==='Open saved result').props.onClick();assert.deepEqual(h.navigation.at(-1)[2],{replace:true,discard:true});});
check('uncertain payment exposes read-only verification link and disabled submit with retained input',async h=>{const vm=await fields(h,'withholding_new');h.response(()=>Promise.reject(Error('Synthetic lost response')));await vm.save();const tree=expand(h.component(workspaceFile,'PayrollContent'));assert.match(text(tree),/write outcome is uncertain/);assert.match(text(tree),/submission is locked/);const link=nodes(tree,'a').find(n=>text(n)==='Open read-only verification');assert.equal(link.props.target,'_blank');assert.equal(link.props.rel,'noopener');assert.ok(!/\/new/.test(link.props.href));assert.ok(nodes(tree,'button').filter(n=>n.props.type==='submit').every(n=>n.props.disabled));assert.equal(h.render().values.amount,'20.10');});
check('failed editor read offers read-only Retry and preserves unsaved field state',async h=>{await fields(h,'profile_edit');const old=h.render().values.notes;h.response(()=>fail(503,'Synthetic loading failed'));await h.render().load();const tree=expand(h.component(workspaceFile,'PayrollContent'));assert.match(text(tree),/Payroll setup unavailable/);assert.match(text(tree),/draft inputs remain preserved/);assert.equal(nodes(tree,'form').length,0);assert.ok(nodes(tree,'button').some(n=>text(n)==='Retry loading'));assert.equal(h.render().values.notes,old);});
check('withholding date change hides old currency/accounts immediately and invalidates old submit callback',async h=>{const old=await fields(h,'withholding_new');old.change('payment_date','2026-11-02');await old.save();const pending=h.render();assert.equal(pending.data.withholding,undefined);assert.equal(pending.canSubmit,false);assert.equal(writes(h).length,0);h.response(()=>ok({currency:'EUR',liability_balance:'50.00',accounts:[{id:'new-eur-account',name:'Synthetic dated EUR',balance:'100.00'}]}));await h.flush();const now=h.render();assert.equal(now.data.withholding.currency,'EUR');assert.equal(now.values.account_id,'syn-account','retain input, but do not authorize stale account');assert.equal(now.canSubmit,false);});
check('late old-date withholding response cannot restore previous currency after newer dated read',async h=>{await fields(h,'withholding_new');let resolve;h.response(()=>new Promise(r=>resolve=r));change(h,{payment_date:'2026-11-02'});await h.flush();change(h,{payment_date:'2026-11-03'});h.response(()=>ok({currency:'EUR',liability_balance:'50.00',accounts:[{id:'new-eur-account',name:'Synthetic dated EUR',balance:'100.00'}]}));await h.flush();h.render();resolve(ok(f.withholding));await settle();assert.equal(h.render().data.withholding.currency,'EUR');assert.equal(h.render().canSubmit,false);});
check('legacy run summary may omit entry details while full document must match employee count',async h=>{h.response((url,options)=>url==='/api/payroll/runs'?ok([{...f.run,entries:[]}]):h.defaultResponse(url,options));const browse=await ready(h);assert.equal(browse.data.runs[0].employee_count,1);assert.equal(browse.data.runs[0].entries.length,0);h.pathname('/dashboard/payroll/runs/syn-run');h.response(()=>ok({...f.run,entries:[]}));h.render();await h.flush();const detail=h.render();assert.equal(detail.run,undefined);assert.match(detail.errors.run,/does not match/);});
const ownPayslipFile='src/components/payroll/employee-payslip.tsx',adminPayslipFile='src/components/payroll/manager-payslip.tsx';
const adjustment={id:'syn-adjustment',reason:'Reviewed own synthetic change',created_at:'2026-10-26T00:00:00Z',before:{base_salary:'1200.00',allowance_total:'12.34',deduction_total:'0.00',tax_amount:'9.00',gross_pay:'1212.34',net_pay:'1203.34'},after:{base_salary:'1200.00',allowance_total:'12.34',deduction_total:'0.00',tax_amount:'10.00',gross_pay:'1212.34',net_pay:'1202.34'}};
const ownPayslip={organization:{name:'Synthetic Company',timezone:'Asia/Dhaka'},run:{...f.run,status:'approved',period_start:f.period.period_start,period_end:f.period.period_end,pay_date:f.period.pay_date},entry:{...f.entry,adjustments:[adjustment]}};
check('own payslip uses only existing authenticated-self endpoint and selected entry history',async h=>{h.params({entryId:f.entry.id});h.response(()=>ok({...ownPayslip,other_employees:[{employee_name:'Must not render other employee',net_pay:'999.99'}],input_snapshot:{employees:['Must not expose whole run input']}}));let tree=await h.mount();tree=expand(tree);assert.deepEqual(h.requests.map(r=>r.url),['/api/hr/self/payslips/syn-entry']);assert.ok(h.requests.every(r=>!r.options?.method));assert.match(text(tree),/Synthetic Employee/);assert.match(text(tree),/Reviewed own synthetic change/);assert.doesNotMatch(text(tree),/Must not render|Must not expose/);assert.match(text(tree),/Only your entry/);assert.equal(nodes(tree,'form').length,0);},'EmployeePayslipContent',ownPayslipFile);
check('own payslip keeps exact large cents and existing deductions plus tax sum',async h=>{h.params({entryId:f.entry.id});h.response(()=>ok({...ownPayslip,entry:{...ownPayslip.entry,net_pay:'9007199254740993.01',deduction_total:'0.10',tax_amount:'0.20'}}));const tree=expand(await h.mount());assert.match(text(tree),/USD 9,007,199,254,740,993.01/);assert.match(text(tree),/Total deductionsUSD 0.30/);},'EmployeePayslipContent',ownPayslipFile);
for(const status of ['draft','reversed','cancelled'])check(`own payslip rejects ${status} response rather than displaying finalized salary`,async h=>{h.params({entryId:f.entry.id});h.response(()=>ok({...ownPayslip,run:{...ownPayslip.run,status}}));const tree=expand(await h.mount());assert.match(text(tree),/could not be verified/);assert.doesNotMatch(text(tree),/Synthetic Employee|1,202.34/);},'EmployeePayslipContent',ownPayslipFile);
for(const patch of [{entry:{...ownPayslip.entry,id:'other-entry'}},{entry:{...ownPayslip.entry,net_pay:1202.34}},{organization:null}])check('malformed/mismatched own payslip remains unavailable, never stale salary data',async h=>{h.params({entryId:f.entry.id});h.response(()=>ok({...ownPayslip,...patch}));const tree=expand(await h.mount());assert.match(text(tree),/could not be verified/);assert.doesNotMatch(text(tree),/Synthetic Employee|1,202.34/);},'EmployeePayslipContent',ownPayslipFile);
check('own payslip preserves HR return link and Print callback without mutation',async h=>{h.params({entryId:f.entry.id});h.response(()=>ok(ownPayslip));const tree=expand(await h.mount());assert.equal(nodes(tree,'NextLink')[0].props.href,'/dashboard/hr/me');nodes(tree,'button').find(n=>text(n)==='Print / Save PDF').props.onClick();assert.deepEqual(h.navigation,[['print']]);assert.equal(writes(h).length,0);},'EmployeePayslipContent',ownPayslipFile);
check('late unmounted own-payslip failure cannot expose notice in another session',async h=>{h.params({entryId:f.entry.id});let resolve;h.response(()=>new Promise(r=>resolve=r));h.render();await h.flush();h.unmount();resolve(fail(401,'Stale private failure'));await settle();assert.doesNotMatch(text(expand(h.render())),/Stale private failure/);assert.equal(h.navigation.length,0);},'EmployeePayslipContent',ownPayslipFile);
for(const [kind,change]of [['company',h=>h.tenant('company-b')],['membership',h=>h.membership('membership-b')],['role',h=>h.role('role-b')],['permissions',h=>h.permissions(['hr.self'])],['entry',h=>h.params({entryId:'entry-b'})]])check(`own payslip ${kind} boundary remounts salary state`,h=>{h.params({entryId:f.entry.id});const a=h.component(ownPayslipFile,'EmployeePayslipPage').key;change(h);const b=h.component(ownPayslipFile,'EmployeePayslipPage').key;assert.notEqual(a,b);});
check('manager payslip reads original run and tenant endpoints but renders only selected entry',async h=>{h.params({runId:f.run.id,entryId:f.entry.id});const other={...f.entry,id:'other-entry',employee_name:'Other private employee',notes:'Other private note',adjustments:[{...adjustment,reason:'Other private history'}]},run={...f.run,employee_count:2,entries:[{...f.entry,adjustments:[adjustment]},other]};h.response(url=>ok(url==='/api/tenant'?{organization:{name:'Synthetic Company'}}:run));const tree=expand(await h.mount());assert.deepEqual(h.requests.map(r=>r.url),['/api/payroll/runs/syn-run','/api/tenant']);assert.match(text(tree),/Synthetic Employee/);assert.match(text(tree),/Reviewed own synthetic change/);assert.doesNotMatch(text(tree),/Other private employee|Other private note|Other private history/);assert.equal(nodes(tree,'form').length,0);},'PayrollPayslipContent',adminPayslipFile);
check('manager draft payslip keeps truthful draft disclaimer and original Print/Close controls',async h=>{h.params({runId:f.run.id,entryId:f.entry.id});h.response(url=>ok(url==='/api/tenant'?{organization:{name:'Synthetic Company'}}:f.run));const tree=expand(await h.mount());assert.match(text(tree),/draft payroll statement, not an approved payroll record/);nodes(tree,'button').find(n=>text(n)==='Print / Save PDF').props.onClick();nodes(tree,'button').find(n=>text(n)==='Close').props.onClick();assert.deepEqual(h.navigation,[['print'],['close']]);},'PayrollPayslipContent',adminPayslipFile);
check('manager payslip missing selected entry cannot substitute first employee',async h=>{h.params({runId:f.run.id,entryId:'missing'});h.response(url=>ok(url==='/api/tenant'?{organization:{name:'Synthetic Company'}}:f.run));const tree=expand(await h.mount());assert.match(text(tree),/Payslip entry not found/);assert.doesNotMatch(text(tree),/Synthetic Employee|1,202.34/);},'PayrollPayslipContent',adminPayslipFile);
check('manager payslip wrong run identity fails closed before rendering totals',async h=>{h.params({runId:f.run.id,entryId:f.entry.id});h.response(url=>ok(url==='/api/tenant'?{organization:{name:'Synthetic Company'}}:{...f.run,id:'other-run'}));const tree=expand(await h.mount());assert.match(text(tree),/could not be verified/);assert.doesNotMatch(text(tree),/Synthetic Employee|1,202.34/);},'PayrollPayslipContent',adminPayslipFile);
check('late unmounted manager payslip response cannot expose old run or error',async h=>{h.params({runId:f.run.id,entryId:f.entry.id});const delayed=[];h.response(()=>new Promise(r=>delayed.push(r)));h.render();await h.flush();h.unmount();delayed.forEach(resolve=>resolve(fail(403,'Stale manager payroll')));await settle();assert.doesNotMatch(text(expand(h.render())),/Stale manager payroll|Synthetic Employee/);},'PayrollPayslipContent',adminPayslipFile);
check('manage-only committed period returns to dashboard rather than attempting forbidden payroll read',async h=>{h.permissions(['payroll.manage']);await fields(h,'period_new');await h.render().save();const tree=expand(h.component(workspaceFile,'PayrollContent'));assert.match(text(tree),/Return to dashboard/);nodes(tree,'button').find(n=>text(n)==='Return to dashboard').props.onClick();assert.equal(h.navigation.at(-1)[1],'/dashboard');assert.equal(h.requests.length,1);});
check('policy version409 retains explicit configuration/reason and never increments expected version locally',async h=>{const vm=await fields(h,'policy_new'),before={...vm.values};h.response(()=>fail(409,'Synthetic policy version conflict'));await vm.save();const now=h.render();assert.deepEqual(now.values,before);assert.equal(now.committed,false);assert.equal(now.uncertain,false);assert.match(now.error,/version conflict/);assert.equal(bodies(h)[0].expected_prior_version,1);assert.equal(writes(h).length,1);});
for(const version of [0,1])check(`v${version} draft confirmation truthfully states its reviewed-input guarantee`,async h=>{await fields(h,'run_new');if(version===0){h.response((url,options)=>url.endsWith('/preview')?ok({...f.preview,mode:'manual',policy_version:0,calculation:{...f.preview.calculation,mode:'manual',policy_version:0,policy_id:null}}):h.defaultResponse(url,options));await h.render().requestPreview();h.render();}h.confirm(false);await h.render().save();assert.equal(writes(h).length,0);if(version===0){assert.match(h.prompts[0],/may differ from this preview/);assert.match(h.prompts[0],/does not enforce a reviewed-input digest/);assert.doesNotMatch(h.prompts[0],/will verify the reviewed inputs/);}else assert.match(h.prompts[0],/will verify the reviewed inputs/);assert.match(h.prompts[0],/No payment is made/);});
check('manual initial snapshot retains original totals and duplicate component rows after current amounts change',h=>{const snapshot={method:'manual_latest_overlapping_profile',automatic_proration:false,totals:{base_salary:'100.00',allowance_total:'5.00',deduction_total:'2.00',tax_amount:'0.00',gross_pay:'105.00',net_pay:'103.00'},allowances:[{name:'Bonus',amount:'2.00',source_profile_id:'old-profile',source_component_index:0},{name:'Bonus',amount:'3.00',source_profile_id:'old-profile',source_component_index:1}],deductions:[{name:'Manual deduction',amount:'2.00',source_profile_id:'old-profile',source_component_index:0}]};h.component(breakdownFile,'PayrollBreakdown',{snapshot,currency:'USD'}).props.onToggle({currentTarget:{open:true}});const tree=expand(h.component(breakdownFile,'PayrollBreakdown',{snapshot,currency:'USD'})),copy=text(tree);for(const amount of ['100.00','105.00','103.00','2.00','3.00'])assert.match(copy,new RegExp('USD '+amount.replace('.','\\.')));assert.ok((copy.match(/Bonus/g)||[]).length>=2);assert.match(copy,/Manual deduction/);assert.match(copy,/immutable initial calculation/);assert.doesNotMatch(copy,/1,202.34/);});
check('component proration explanation preserves source identity, exact fractions and rounded result',h=>{const snapshot={method:'working_day',component_calculations:[{category:'default_allowances',source_profile_id:'source-one',source_component_index:0,name:'Bonus',treatment:'prorate_profile_segments',unrounded_amount_fraction:{numerator:'90071992547409931234567',denominator:'260000000000000000000000'},unrounded_amount_display:'0.346430740566961273979103846',display_is_approximation:true,rounded_amount:'0.35'},{category:'default_allowances',source_profile_id:'source-two',source_component_index:0,name:'Bonus',treatment:'fixed_latest',unrounded_amount_fraction:{numerator:'2',denominator:'1'},unrounded_amount_display:'2',display_is_approximation:false,rounded_amount:'2.00'}]};h.component(breakdownFile,'PayrollBreakdown',{snapshot,currency:'USD'}).props.onToggle({currentTarget:{open:true}});const tree=expand(h.component(breakdownFile,'PayrollBreakdown',{snapshot,currency:'USD'})),copy=text(tree);assert.match(copy,/source-one/);assert.match(copy,/source-two/);assert.match(copy,/90071992547409931234567/);assert.match(copy,/260000000000000000000000/);assert.match(copy,/USD 0.35/);assert.match(copy,/USD 2.00/);assert.match(copy,/Approximate|approximate/);assert.ok((copy.match(/Bonus/g)||[]).length>=2);});
check('empty adjustment history does not falsely imply legacy audits are unsupported',h=>{const copy=text(h.component(breakdownFile,'PayrollAdjustmentHistory',{adjustments:[],currency:'USD'}));assert.match(copy,/No.*monetary adjustment/);assert.doesNotMatch(copy,/versioned monetary adjustment/);});
const refreshedPolicy={...f.policy,latest_version:2,scheduled_versions:[{...f.policyVersion,id:'scheduled-two',version:2,effective_from:'2026-12-01',activation_reason:'Synthetic concurrent policy change'}]};
async function conflict(h){const vm=await fields(h,'policy_new');h.response(()=>fail(409,'Synthetic policy version conflict'));await vm.save();return h.render();}
check('policy409 synchronously locks repeats until explicit authoritative reload and review',async h=>{const vm=await fields(h,'policy_new');h.response(()=>fail(409,'Synthetic policy version conflict'));await vm.save();await vm.save();let now=h.render();assert.equal(now.policyRecovery,'reload');assert.equal(now.canSubmit,false);assert.equal(writes(h).length,1);now.acceptPolicyContext();assert.equal(h.render().policyRecovery,'reload');assert.equal(h.requests.length,2,'initial GET and one POST only');});
check('policy409 successful reload retains all fields and requires acknowledgement before manual activation',async h=>{let now=await conflict(h);const before={...now.values};h.response((url,options)=>options?.method?ok({id:'created-version'}):ok(refreshedPolicy));await now.reloadPolicyContext();now=h.render();assert.equal(now.policyRecovery,'review');assert.equal(now.policyRecoveryContext.latest_version,2);assert.deepEqual(now.values,before);assert.equal(now.canSubmit,false);assert.equal(writes(h).length,1);assert.equal(h.requests.at(-1).url,'/api/payroll/policy');assert.equal(h.requests.at(-1).options?.method,undefined);now.acceptPolicyContext();now=h.render();assert.equal(now.canSubmit,true);assert.equal(writes(h).length,1,'acknowledgement is not activation');await now.save();assert.equal(writes(h).length,2);assert.equal(bodies(h)[1].expected_prior_version,2);assert.equal(bodies(h)[1].activation_reason,before.activation_reason);assert.equal(h.render().committed,true);});
check('failed policy context reload retains form and last verified context without unlocking writes',async h=>{let now=await conflict(h);const before={...now.values},context=now.policyRecoveryContext;h.response(()=>fail(503,'Synthetic reload unavailable'));await now.reloadPolicyContext();now=h.render();assert.equal(now.policyRecovery,'reload');assert.deepEqual(now.policyRecoveryContext,context);assert.deepEqual(now.values,before);assert.equal(now.canSubmit,false);assert.match(now.errors.policy,/reload unavailable/);now.acceptPolicyContext();await h.render().save();assert.equal(writes(h).length,1);const tree=expand(h.component(workspaceFile,'PayrollContent'));assert.match(text(tree),/Last successfully loaded context · not confirmed current/);assert.ok(nodes(tree,'button').some(n=>text(n)==='Reload latest policy context'));});
check('policy context acknowledgement rejects a newer unreviewed authoritative response',async h=>{await conflict(h);h.response(()=>ok(refreshedPolicy));await h.render().reloadPolicyContext();const reviewed=h.render();assert.equal(reviewed.policyRecovery,'review');h.response(()=>ok({...refreshedPolicy,latest_version:3}));await reviewed.load();const newer=h.render();newer.acceptPolicyContext();assert.equal(h.render().policyRecovery,'review');assert.equal(h.render().canSubmit,false);assert.equal(writes(h).length,1);});
check('policy recovery offers explicit read/review controls and never form-submits from them',async h=>{await conflict(h);let tree=expand(h.component(editorsFile,'PayrollPolicyRecovery',{vm:h.render()}));let buttons=nodes(tree,'button');assert.equal(buttons.length,1);assert.equal(buttons[0].props.type,'button');assert.equal(text(buttons[0]),'Reload latest policy context');h.response(()=>ok(refreshedPolicy));buttons[0].props.onClick();await settle();tree=expand(h.component(editorsFile,'PayrollPolicyRecovery',{vm:h.render()}));buttons=nodes(tree,'button');assert.equal(buttons.length,2);assert.ok(buttons.every(n=>n.props.type==='button'));assert.match(text(tree),/Scheduled version 2/);assert.match(text(tree),/Synthetic concurrent policy change/);buttons[1].props.onClick();assert.equal(h.render().policyRecovery,null);assert.equal(writes(h).length,1);});
check('policy context duplicate reload is latched and old unmounted401 has no effect',async h=>{const now=await conflict(h),before=h.requests.length;let resolve;h.response(()=>new Promise(r=>resolve=r));const first=now.reloadPolicyContext(),second=now.reloadPolicyContext();assert.equal(h.requests.length,before+1);h.unmount();resolve(fail(401));await Promise.all([first,second]);assert.equal(h.navigation.length,0);assert.equal(h.render().policyRecovery,'reload');assert.equal(writes(h).length,1);});
